const Festval_serch_details = () => {
  const [defaultArea, area] = useState("전국");
  const [defaultDate, date] = useState("월별");

  const [isSelect,setIsSelect] = useState(0);
  const [isCalender,setIsCalender] = useState(0);

  const onClickItem = (e) =>{
    
    setIsSelect(0);
    
    //console.log(e.target.innerText);
    area(e.target.innerText);        
  }

  const isHover = (e) => {
    e.target.style = 'background-color:#FFBD60';
  }

  const setHover = (e) => {
    e.target.style = '';
  }

  return(
    <div className='search_box'>
        <div className='search_class'>                     
          <button id='class_ground' className='select_button' onClick={()=>setIsSelect(1)}>{defaultArea}</button>
          <button id='class_date' className='select_button'>{defaultDate}</button>                       
          <div id="select_hidden">
            <ul id="area_selete" style={{display: isSelect ? "block" : "none"}}>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>전국</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>서울</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>인천</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>대전</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>대구</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>광주</li>
              <li className="select_item" onClick={onClickItem} onMouseEnter={isHover} onMouseLeave={setHover}>부산</li>              
            </ul>
            <div id="date_calender">
              <ul className="calender_date">
                <li className="calender_item years_item">올해</li>                
              </ul>
              <ul className="calender_date">
                <li className="calender_item">1월</li>
                <li className="calender_item">2월</li>
                <li className="calender_item">3월</li>
                <li className="calender_item">4월</li>
                <li className="calender_item">5월</li>
                <li className="calender_item">6월</li>
                <li className="calender_item">7월</li>
                <li className="calender_item">8월</li>
                <li className="calender_item">9월</li>
                <li className="calender_item">10월</li>
                <li className="calender_item">11월</li>
                <li className="calender_item">12월</li>
              </ul>
            </div>
          </div>  
        </div>          
        
        <div className='thema_class'>
          <div id="class_thema1" className='thema_box'>계절테마1</div>
          <div id="class_thema2" className='thema_box'>계절테마2</div>
          <div id="" className='thema_box'>계절테마3</div>
          <div id="class_thema4" className='thema_box'>계절테마4</div>
        </div>
      </div>
  );

};// Festval_search_detauls close


export default Festval_serch_details;
